using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.Drawing.Text;using System.Collections.Generic;using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 sealed class ThemeRenderer:IDisposable {
  readonly ThemeDocument theme;readonly Bitmap canvas,rotated;readonly Graphics graphics,rotationGraphics;readonly TurboCodec codec=new TurboCodec();readonly Dictionary<string,Font> fonts=new Dictionary<string,Font>();readonly Dictionary<string,Image> images=new Dictionary<string,Image>();readonly PrivateFontCollection nativeFonts=new PrivateFontCollection();readonly Dictionary<string,FontFamily> nativeFamilies=new Dictionary<string,FontFamily>(StringComparer.OrdinalIgnoreCase);readonly int rotation;readonly bool renderStatic,renderDynamic;
  public bool Dynamic{get{return renderDynamic&&theme.Texts.OfType<JObject>().Any(t=>((string)t["TextType"]??"DIYTextList")!="DIYTextList");}}
  public bool HasLayers{get{return theme.Texts.Count>0||theme.Images.Count>0||(theme.Json["EnhancedShapes"] as JArray??new JArray()).Count>0;}}
  public ThemeRenderer(ThemeDocument document,int angle,bool nativeBackground=false,bool drawStatic=true,bool drawDynamic=true){theme=document;renderStatic=drawStatic;renderDynamic=drawDynamic;rotation=((angle%360)+360)%360;bool swap=rotation==90||rotation==270;canvas=new Bitmap(nativeBackground&&swap?theme.Height:theme.Width,nativeBackground&&swap?theme.Width:theme.Height,PixelFormat.Format24bppRgb);graphics=Graphics.FromImage(canvas);graphics.CompositingQuality=CompositingQuality.HighSpeed;graphics.InterpolationMode=InterpolationMode.Bilinear;graphics.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;if(nativeBackground&&rotation!=0)Transform(graphics,canvas.Width,canvas.Height,rotation);else if(rotation!=0){rotated=new Bitmap(swap?canvas.Height:canvas.Width,swap?canvas.Width:canvas.Height,PixelFormat.Format24bppRgb);rotationGraphics=Graphics.FromImage(rotated);}string fontFolder=Path.Combine(theme.Folder,"font");if(Directory.Exists(fontFolder))foreach(string file in Directory.GetFiles(fontFolder,"*.ttf"))try{nativeFonts.AddFontFile(file);}catch{}foreach(var family in nativeFonts.Families)nativeFamilies[family.Name]=family;if(renderStatic)foreach(JObject layer in theme.Images.OfType<JObject>()){string path=theme.Resolve((string)layer["Image"]);if(File.Exists(path)&&!images.ContainsKey(path))try{using(var source=Image.FromFile(path))images[path]=new Bitmap(source);}catch{}}}
  static void Transform(Graphics target,int width,int height,int angle){target.ResetTransform();if(angle==90){target.TranslateTransform(width,0);target.RotateTransform(90);}else if(angle==180){target.TranslateTransform(width,height);target.RotateTransform(180);}else if(angle==270){target.TranslateTransform(0,height);target.RotateTransform(270);}}
  public byte[] Compose(byte[] background,SensorSnapshot sensors,int quality){
   if(background!=null)codec.Decode(background,canvas);else{graphics.Clear(Color.Black);if(!theme.Video&&File.Exists(theme.Background))using(var image=Image.FromFile(theme.Background)){var state=graphics.Save();try{if(theme.BackgroundRotation%360!=0){graphics.TranslateTransform(theme.Width/2f,theme.Height/2f);graphics.RotateTransform(theme.BackgroundRotation);graphics.TranslateTransform(-theme.Width/2f,-theme.Height/2f);}if(theme.BackgroundFit=="region"){var region=theme.BackgroundRegion;graphics.DrawImage(image,new RectangleF(0,0,theme.Width,theme.Height),new RectangleF(region.X*image.Width,region.Y*image.Height,region.Width*image.Width,region.Height*image.Height),GraphicsUnit.Pixel);}else{float sx=theme.Width/(float)image.Width,sy=theme.Height/(float)image.Height;float scale=theme.BackgroundFit=="cover"?Math.Max(sx,sy):Math.Min(sx,sy);float width=theme.BackgroundFit=="fill"?theme.Width:image.Width*scale,height=theme.BackgroundFit=="fill"?theme.Height:image.Height*scale;graphics.DrawImage(image,(theme.Width-width)/2,(theme.Height-height)/2,width,height);}}finally{graphics.Restore(state);}}}
   var layers=new List<Tuple<int,Action>>();if(renderStatic)foreach(JObject shape in (theme.Json["EnhancedShapes"] as JArray??new JArray()).OfType<JObject>()){var item=shape;layers.Add(Tuple.Create((int?)item["z"]??0,new Action(()=>{using(var brush=new SolidBrush(ThemeDocument.ParseColor((string)item["color"])))graphics.FillRectangle(brush,(float?)item["x"]??0,(float?)item["y"]??0,(float?)item["width"]??100,(float?)item["height"]??2);})));
   }if(renderStatic)foreach(JObject image in theme.Images.OfType<JObject>()){var item=image;layers.Add(Tuple.Create((int?)item["ZIndex"]??0,new Action(()=>{string path=theme.Resolve((string)item["Image"]);Image loaded;if(images.TryGetValue(path,out loaded))graphics.DrawImage(loaded,(float?)item["Left"]??0,(float?)item["Top"]??0,(float?)item["Width"]??loaded.Width,(float?)item["Height"]??loaded.Height);})));
   }foreach(JObject text in theme.Texts.OfType<JObject>()){var item=text;bool bound=((string)item["TextType"]??"DIYTextList")!="DIYTextList";if(bound?!renderDynamic:!renderStatic)continue;layers.Add(Tuple.Create((int?)item["ZIndex"]??0,new Action(()=>DrawText(item,sensors))));}foreach(var layer in layers.OrderBy(x=>x.Item1))layer.Item2();
   if(rotated==null)return codec.Encode(canvas,quality);rotationGraphics.ResetTransform();if(rotation==90){rotationGraphics.TranslateTransform(rotated.Width,0);rotationGraphics.RotateTransform(90);}else if(rotation==180){rotationGraphics.TranslateTransform(rotated.Width,rotated.Height);rotationGraphics.RotateTransform(180);}else if(rotation==270){rotationGraphics.TranslateTransform(0,rotated.Height);rotationGraphics.RotateTransform(270);}rotationGraphics.DrawImageUnscaled(canvas,0,0);return codec.Encode(rotated,quality);
  }
  void DrawText(JObject item,SensorSnapshot sensors){string type=(string)item["TextType"]??"DIYTextList",text=(string)item["Text"]??"";if(type!="DIYTextList")text=ThemeDocument.BoundValue(item,sensors);string name=(string)item["FontName"]??"Segoe UI";float size=Math.Max(6,Math.Min(500,(float?)item["FontSize"]??32));FontStyle style=((bool?)item["Bold"]==true?FontStyle.Bold:FontStyle.Regular)|((bool?)item["Italic"]==true?FontStyle.Italic:FontStyle.Regular)|((bool?)item["Underline"]==true?FontStyle.Underline:FontStyle.Regular);string key=name+"|"+size+"|"+style;Font font;if(!fonts.TryGetValue(key,out font)){try{FontFamily family;if(nativeFamilies.TryGetValue(name,out family))font=new Font(family,size,style,GraphicsUnit.Pixel);else font=new Font(name,size,style,GraphicsUnit.Pixel);}catch{font=new Font("Segoe UI",size,style,GraphicsUnit.Pixel);}fonts[key]=font;}using(var brush=new SolidBrush(ThemeDocument.ParseColor((string)item["Color"])))graphics.DrawString(text,font,brush,(float?)item["Left"]??0,(float?)item["Top"]??0,StringFormat.GenericTypographic);}
  public void Dispose(){foreach(var font in fonts.Values)font.Dispose();foreach(var image in images.Values)image.Dispose();nativeFonts.Dispose();if(rotationGraphics!=null)rotationGraphics.Dispose();if(rotated!=null)rotated.Dispose();graphics.Dispose();canvas.Dispose();codec.Dispose();}
 }
}
